        // Delphi: function CTL_CODE(DeviceType, Func, Method, Access: WORD): DWORD
        public static uint CTL_CODE(ushort DeviceType, ushort Func, ushort Method, ushort Access)
        {
            uint Result = (uint)0;
            Result = (uint)(DeviceType << 16 | Access << 14 | Func << 2 | Method);
            return Result;
        }

