            Result = (ushort)((CtrlCode & (uint)0xFFFF0000) >> 16);
            return Result;
        }

        // Delphi: function IsRecognizedPartition(PartitionType: DWORD): Boolean
        public static bool IsRecognizedPartition(uint PartitionType)
        {
            bool Result = false;
            Result = (PartitionType & PARTITION_NTFT) != 0 && (PartitionType & ~0xC0) == PARTITION_FAT_12 || (PartitionType & PARTITION_NTFT) != 0 && (PartitionType & ~0xC0) == PARTITION_IFS || (PartitionType & PARTITION_NTFT) != 0 && (PartitionType & ~0xC0) == PARTITION_HUGE || (PartitionType & PARTITION_NTFT) != 0 && (PartitionType & ~0xC0) == PARTITION_FAT32 || (PartitionType & PARTITION_NTFT) != 0 && (PartitionType & ~0xC0) == PARTITION_FAT32_XINT13 || (PartitionType & PARTITION_NTFT) != 0 && (PartitionType & ~0xC0) == PARTITION_XINT13 || PartitionType == PARTITION_FAT_12 || PartitionType == PARTITION_FAT_16 || PartitionType == PARTITION_IFS || PartitionType == PARTITION_HUGE || PartitionType == PARTITION_FAT32 || PartitionType == PARTITION_FAT32_XINT13 || PartitionType == PARTITION_XINT13;
            return Result;
        }

        // Delphi: function IsContainerPartition(PartitionType: DWORD): Boolean
        public static bool IsContainerPartition(uint PartitionType)
        {
            bool Result = false;
            Result = PartitionType == PARTITION_EXTENDED || PartitionType == PARTITION_XINT13_EXTENDED;
            return Result;
        }

        // Delphi: function IsFTPartition(PartitionType: DWORD): Boolean
        public static bool IsFTPartition(uint PartitionType)
        {
            bool Result = false;
            Result = (PartitionType & PARTITION_NTFT) != 0 && IsRecognizedPartition(PartitionType);
            return Result;
        }

